			case "npc_interaction":
				return "Must interact with specified NPC";
			case "any_npc":
				return "Must interact with any NPC";
			default:
				return "Action constraint";
		}
	}

	@Override
	public String getConstraintType()
	{
		return "action";
	}

	// Getters and setters
